//! Shared test helpers for the `paigasus-helikon-runtime-axum` integration tests.
//!
//! This module is compiled into every integration-test binary; not every helper
//! is used by every binary, so dead-code is allowed module-wide.
#![allow(dead_code)]

use std::{
    net::SocketAddr,
    sync::{Arc, Mutex},
    time::Duration,
};

use async_trait::async_trait;
use futures_util::stream::{self, BoxStream, StreamExt as _};
use paigasus_helikon_core::{
    Agent, AgentError, AgentEvent, AgentInput, ContentPart, Item, RunConfig, RunContext, RunError,
    RunResult, RunResultStreaming, Runner, TokenUsage,
};
use paigasus_helikon_runtime_axum::{AgentServer, InMemorySessionProvider, SessionProvider};

/// A test [`Agent`] that emits a fixed sequence of events rather than
/// talking to any real model.
pub struct ScriptedAgent {
    /// Agent name returned by [`Agent::name`].
    pub name: String,
    /// Events to emit on each [`Agent::run`] call.
    pub events: Vec<AgentEvent>,
}

#[async_trait]
impl<Ctx: Send + Sync + 'static> Agent<Ctx> for ScriptedAgent {
    fn name(&self) -> &str {
        &self.name
    }

    fn description(&self) -> &str {
        "scripted test agent"
    }

    async fn run(
        &self,
        _ctx: RunContext<Ctx>,
        _input: AgentInput,
    ) -> Result<BoxStream<'static, AgentEvent>, AgentError> {
        Ok(stream::iter(self.events.clone()).boxed())
    }
}

/// Returns a minimal event sequence: one assistant "echo" message followed by
/// [`AgentEvent::RunCompleted`].
pub fn echo_script() -> Vec<AgentEvent> {
    vec![
        AgentEvent::MessageOutput {
            item: Item::AssistantMessage {
                content: vec![ContentPart::Text {
                    text: "echo".to_owned(),
                }],
                agent: None,
            },
        },
        AgentEvent::RunCompleted {
            usage: TokenUsage::default(),
        },
    ]
}

/// Build an [`AgentServer`] mounting a single `echo` [`ScriptedAgent`], bind it
/// to an ephemeral loopback port, spawn the serve loop, and return the bound
/// address.
pub async fn spawn_echo_server() -> SocketAddr {
    let server = AgentServer::<()>::builder()
        .with_default_context()
        .agent(Arc::new(ScriptedAgent {
            name: "echo".into(),
            events: echo_script(),
        }))
        .build()
        .expect("server builds");

    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("bind ephemeral port");
    let addr = listener.local_addr().expect("local addr");

    tokio::spawn(async move {
        server
            .serve_with_listener(listener)
            .await
            .expect("serve loop");
    });

    addr
}

/// Parse the `data:` lines of a Server-Sent-Events body back into a
/// `Vec<AgentEvent>`, in order. Non-`data:` lines (blank separators, `event:`
/// type tags) are ignored.
pub fn parse_sse(text: &str) -> Vec<AgentEvent> {
    text.lines()
        .filter_map(|line| line.strip_prefix("data:"))
    Event::default().data(serde_json::to_string(ev).expect("AgentEvent serializes"))
}

// ── Tests ─────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use crate::AgentCoreServer;
    use async_trait::async_trait;
    use axum::{
        body::Body,
        http::{Request as HttpRequest, StatusCode},
    };
    use futures_util::stream::BoxStream;
    use paigasus_helikon_core::{Agent, AgentError, ContentPart, RunContext, TokenUsage};
    use tower::ServiceExt as _;

    // ── (a) DTO parsing ────────────────────────────────────────────────────

    #[test]
    fn messages_form_parses() {
        let req: InvocationRequest = serde_json::from_str(
            r#"{"messages":[{"type":"user_message","content":[{"type":"text","text":"hi"}]}]}"#,
        )
        .unwrap();
        assert!(matches!(req, InvocationRequest::Messages { messages } if messages.len() == 1));
    }

    #[test]
    fn prompt_form_parses() {
        let req: InvocationRequest = serde_json::from_str(r#"{"prompt":"hi"}"#).unwrap();
        assert!(matches!(req, InvocationRequest::Prompt { prompt } if prompt == "hi"));
    }

    #[test]
    fn input_form_parses() {
        let req: InvocationRequest = serde_json::from_str(r#"{"input":"hi"}"#).unwrap();
        assert!(matches!(req, InvocationRequest::Input { input } if input == "hi"));
    }

    /// Documents the untagged enum's actual (and accepted) behavior: an unrecognised
    /// extra key does NOT reject the request — it is silently ignored, and the body
    /// still parses as `Prompt`. See the [`InvocationRequest`] doc for why.
    #[test]
    fn extra_unknown_key_is_tolerated() {
        let req: InvocationRequest = serde_json::from_str(r#"{"prompt":"hi","junk":1}"#).unwrap();
        assert!(matches!(req, InvocationRequest::Prompt { prompt } if prompt == "hi"));
    }

    /// Pins the untagged enum's declared-order resolution: a body carrying BOTH a
